-- Division Wars 2026 rulebook catalog update
-- Run once in Supabase SQL Editor after the competition_state table exists.
-- Preserves entries, participants, audit history, other access assignments,
-- and every non-sample fixture. Ensures the owner has full central-admin access.
do $$
begin
  if not exists (select 1 from public.competition_state where id = 'main') then
    raise exception 'No competition_state row exists. Open the app once with Supabase configured, then rerun this script.';
  end if;
end $$;

update public.competition_state
set state = state || jsonb_build_object(
