  'fixtures', coalesce((select jsonb_agg(fixture) from jsonb_array_elements(coalesce(state->'fixtures', '[]'::jsonb)) as fixture where coalesce(fixture->>'id', '') not like 'sample-%'), '[]'::jsonb),
  'assignments', coalesce((select jsonb_agg(assignment) from jsonb_array_elements(coalesce(state->'assignments', '[]'::jsonb)) as assignment where lower(coalesce(assignment->>'email', '')) <> 'pgp26.shivams@spjimr.org'), '[]'::jsonb) || jsonb_build_array(jsonb_build_object('email', 'pgp26.shivams@spjimr.org', 'role', 'central-admin', 'active', true))
),
version = version + 1,
updated_at = now()
where id = 'main'
returning id, version, jsonb_array_length(state->'sections') as sections, jsonb_array_length(state->'sports') as sports_and_cultural_categories, jsonb_array_length(state->'events') as events, exists(select 1 from jsonb_array_elements(state->'assignments') as owner where lower(owner->>'email') = 'pgp26.shivams@spjimr.org' and owner->>'role' = 'central-admin' and owner->>'active' = 'true') as owner_has_full_access;